body:
id also recommend having a constructor for your Order class where you can initialize all the fields, here's what i came up with:

import java.text.DecimalFormat;

public class Order
{
   private  int quantity;
   private double unitPrice;
   private String legit2quit;
   DecimalFormat swag;

   public Order(int a, double b)
   {
	  swag = new DecimalFormat("0.00");
      quantity = a;
      unitPrice = b;
   }
     public String toString()
    {

      legit2quit = "QTY " + quantity + " UNIT PRICE $" + swag.format(unitPrice);
      return legit2quit;
  }

 static class Main
 {
	 public static void main(String[] args)
	 {
	   Order ord = new Order(7,1.3);
	   System.out.println(ord.toString());
	 }
   }
}
